import math

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # 1. Free space: logarithmic scaling with dynamic normalization by stack height
    if EMP > 0:
        free_space_weight = math.log(EMP + 1) / (math.log(SH + 1) + 1)
    else:
        free_space_weight = 10  # Light penalty for no free space

    # 2. AVG alignment: prioritize stacks with AVG much lower than CUR
    avg_diff = AVG - CUR
    if avg_diff < 0:
        avg_weight = max(0, 1 - (avg_diff / 1000))  # Reward if AVG is significantly below CUR
    else:
        avg_weight = (avg_diff / 1000) * 0.5  # Penalize if AVG is above CUR

    # 3. DIFF: entropy-based weighting, treat unknown containers as highly uncertain
    if DIFF < 1000:
        diff_weight = math.exp(-DIFF / 1000)  # Rapid decay for known containers
    else:
        diff_weight = 0.05  # Moderate penalty for stacks with unknown containers

    # 4. RI normalization: consider RI-to-depth ratio and look-ahead uncertainty
    if SH > 0:
        ri_weight = (RI / (SH + 1)) * (1 + (DIFF / 1000000))  # Adjust based on uncertainty
    else:
        ri_weight = 0.1  # Very low penalty for empty stacks

    # 5. Stack height: logarithmic scaling with adaptive weight
    sh_weight = math.log(SH + 1) if SH < 30 else 5.0  # Encourage shorter stacks

    # 6. Bonus for stacks with fewer blocking containers (RI < 2)
    if RI < 2:
        ri_bonus = 0.5
    else:
        ri_bonus = 0

    # Combine all components for final priority
    priority = free_space_weight + avg_weight + diff_weight + ri_weight + sh_weight + ri_bonus
    return priority
